+		expect(b.watcherManager).toBe(a.watcherManager);
+	});
+
+	it("keeps separate pools for different poll and followSymlinks", () => {
+		const a = watch({ aggregateTimeout: 20 });
+		const b = watch({ aggregateTimeout: 20, poll: 100 });
