+    for (camel_key, kebab_key) in [
+        ("bin", "global-bin-dir"),
+        ("globalPkgDir", "global-dir"),
+        ("userconfig", "npmrc-auth-file"),
+    ] {
+        assert_eq!(
+            where_refused_key_belongs(camel_key),
+            format!("Set it for the machine instead: pnpm config set --global {kebab_key}"),
+        );
+    }
+}
