+    fn new(expected_size: Option<u64>, package_id: &'a str) -> Self {
+        Self {
+            emit: expected_size.is_some_and(|size| size >= Self::BIG_TARBALL_SIZE),
+            last_emit: None,
+            last_emitted_downloaded: 0,
+            downloaded: 0,
